const { useState } = React;

function App() {
  const [destination, setDestination] = useState("");
  const [checkIn, setCheckIn] = useState("");
  const [checkOut, setCheckOut] = useState("");
  const [guests, setGuests] = useState(1);
  const [error, setError] = useState("");

  const handleSearch = (e) => {
    e.preventDefault();
    if (!destination.trim()) {
      setError("Please enter a destination.");
      return;
    }
    if (!checkIn) {
      setError("Please select a check-in date.");
      return;
    }
    if (!checkOut) {
      setError("Please select a check-out date.");
      return;
    }
    if (new Date(checkOut) <= new Date(checkIn)) {
      setError("Check-out date must be after check-in date.");
      return;
    }
    setError("");
    alert(`Searching hotels in ${destination} for ${guests} guest(s) from ${checkIn} to ${checkOut}`);
  };

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #f9f9f9;
          color: #222;
        }
        header {
          background: white;
          border-bottom: 1px solid #ddd;
          padding: 0 20px;
          display: flex;
          align-items: center;
          justify-content: space-between;
          height: 56px;
          font-weight: 600;
          font-size: 1.2rem;
        }
        nav {
          display: flex;
          gap: 24px;
          align-items: center;
          font-weight: 500;
          font-size: 1rem;
        }
        nav a {
          color: #222;
          text-decoration: none;
          cursor: pointer;
          padding: 6px 8px;
          border-radius: 4px;
          transition: background-color 0.2s ease;
        }
        nav a:hover {
          background-color: #eee;
        }
        button.signin {
          background-color: transparent;
          border: 1.5px solid #222;
          border-radius: 4px;
          padding: 6px 14px;
          font-weight: 600;
          cursor: pointer;
          transition: background-color 0.2s ease, color 0.2s ease;
        }
        button.signin:hover {
          background-color: #222;
          color: white;
        }
        .banner {
          width: 100%;
          height: 280px;
          object-fit: cover;
          display: block;
          margin-bottom: 20px;
          user-select: none;
        }
        main {
          max-width: 960px;
          margin: 0 auto 40px;
          padding: 0 20px;
        }
        form.search-card {
          background: white;
          box-shadow: 0 2px 8px rgb(0 0 0 / 0.1);
          border-radius: 8px;
          padding: 16px 20px;
          display: flex;
          gap: 12px;
          align-items: center;
          flex-wrap: wrap;
        }
        form.search-card > * {
          flex: 1 1 140px;
          min-width: 120px;
        }
        label {
          display: flex;
          flex-direction: column;
          font-weight: 600;
          font-size: 0.9rem;
          color: #444;
          margin-bottom: 4px;
          user-select: none;
        }
        input[type="text"],
        input[type="date"],
        select {
          padding: 8px 10px;
          font-size: 1rem;
          border: 1.5px solid #ccc;
          border-radius: 6px;
          outline-offset: 2px;
          outline-color: transparent;
          transition: outline-color 0.2s ease, border-color 0.2s ease;
        }
        input[type="text"]:focus,
        input[type="date"]:focus,
        select:focus {
          border-color: #0077cc;
          outline-color: #0077cc;
        }
        button.search-btn {
          flex: 0 0 100px;
          background-color: #ffeb3b;
          border: none;
          color: #222;
          font-weight: 700;
          font-size: 1rem;
          padding: 10px 0;
          border-radius: 6px;
          cursor: pointer;
          user-select: none;
          transition: background-color 0.2s ease;
        }
        button.search-btn:hover {
          background-color: #fdd835;
        }
        .error-message {
          color: #cc0000;
          font-weight: 600;
          margin-top: 8px;
          flex-basis: 100%;
          font-size: 0.9rem;
        }
      `}</style>
      <header>
        <div style={{ fontWeight: "700", fontSize: "1.3rem" }}>StayFinder</div>
        <nav aria-label="Primary">
          <a href="#hotels" tabIndex={0}>Hotels</a>
          <a href="#flights" tabIndex={0}>Flights</a>
          <a href="#deals" tabIndex={0}>Deals</a>
          <button className="signin" type="button">Sign in</button>
        </nav>
      </header>
      <img
        src="/runtime/photos/travel.jpg"
        alt="Scenic travel destination banner"
        className="banner"
        draggable={false}
      />
      <main>
        <form className="search-card" onSubmit={handleSearch} noValidate>
          <label htmlFor="destination">
            Destination
            <input
              id="destination"
              type="text"
              placeholder="Destination"
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              aria-describedby={error && !destination ? "error-destination" : undefined}
              aria-invalid={error && !destination ? "true" : "false"}
            />
          </label>
          <label htmlFor="checkin">
            Check-in
            <input
              id="checkin"
              type="date"
              value={checkIn}
              onChange={(e) => setCheckIn(e.target.value)}
              aria-describedby={error && !checkIn ? "error-checkin" : undefined}
              aria-invalid={error && !checkIn ? "true" : "false"}
            />
          </label>
          <label htmlFor="checkout">
            Check-out
            <input
              id="checkout"
              type="date"
              value={checkOut}
              onChange={(e) => setCheckOut(e.target.value)}
              aria-describedby={error && (!checkOut || new Date(checkOut) <= new Date(checkIn)) ? "error-checkout" : undefined}
              aria-invalid={error && (!checkOut || new Date(checkOut) <= new Date(checkIn)) ? "true" : "false"}
            />
          </label>
          <label htmlFor="guests">
            Guests
            <select
              id="guests"
              value={guests}
              onChange={(e) => setGuests(Number(e.target.value))}
            >
              {[...Array(10).keys()].map((n) => (
                <option key={n + 1} value={n + 1}>
                  {n + 1}
                </option>
              ))}
            </select>
          </label>
          <button type="submit" className="search-btn">
            Search
          </button>
          {error && (
            <p role="alert" className="error-message" id={
              !destination
                ? "error-destination"
                : !checkIn
                ? "error-checkin"
                : !checkOut || new Date(checkOut) <= new Date(checkIn)
                ? "error-checkout"
                : undefined
            }>
              {error}
            </p>
          )}
        </form>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

